        double c = (a + b) / 2.0;
        double fa = f(a);
        double fc = f(c);
        double fb = f(b);

        double S1 = (b - a) * fc; // Midpoint rule on the whole interval
        double S2 = 0.5 * ((c - a) * (fa + fc) + (b - c) * (fc + fb)); // Midpoint rule on two subintervals

        if (std::abs(S2 - S1) < precision) {
            // If the difference between the two estimates is less than the precision, return S2
            return S2;
        } else {
            // Otherwise, recursively apply the adaptive midpoint rule on the two subintervals
            return adaptive_midpoint(f, a, c, precision) + adaptive_midpoint(f, c, b, precision);
        }

